import{_ as s,a0 as o,w as i,s as a,ao as d,I as r,x as e,a1 as u,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧-使用OpenDNS來保護你的電腦 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧-使用OpenDNS來保護你的電腦 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧-使用OpenDNS來保護你的電腦 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧-使用OpenDNS來保護你的電腦 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips–Protect Your Computers Using OpenDNS’ Secure DNS Infrastructure","title":"每日Ubuntu小技巧-使用OpenDNS來保護你的電腦","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips–Protect Your Computers Using OpenDNS’ Secure DNS Infrastructure.md","filePath":"[post].md"}'),l={name:"201312/Daily Ubuntu Tips–Protect Your Computers Using OpenDNS’ Secure DNS Infrastructure.md"};function D(m,t,S,N,f,T){const n=o("Link");return i(),a("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-使用opendns來保護你的電腦" tabindex="-1">每日Ubuntu小技巧-使用OpenDNS來保護你的電腦 <a class="header-anchor" href="#每日ubuntu小技巧-使用opendns來保護你的電腦" aria-label="Permalink to “每日Ubuntu小技巧-使用OpenDNS來保護你的電腦”">​</a></h1><p>互聯網是個大熔爐。無論是好人還是壞人，都可以和我們一樣連接到網絡。那些製作病毒感染人們電腦的壞蛋以及尋求保護人們的好人們全都連接到同一網絡中。</p><p>就像人們所説的那樣，互聯網是過去所出現的一個最好的東東。它包含着任何人都可以獲取的有價值的信息和資源，且大部分可以免費獲取。一些最著名高校的人提供了免費的高質量課程，可供任何想學習的人來學習。今天，我們都可以連入互聯網真是一件好事情。</p><p>但是有些事情你一定要記住，當你連入互聯網時，你的電腦就成了攻擊的目標。成為病毒，木馬和其它程序破壞的目標。</p><p>正因為此，推薦連入互聯網的電腦都要使用反病毒和反間諜軟件來保護。在有些情況下，即使使用了這些軟件也不能完全保證你的安全。再添加一個安全層總是一個好主意。</p><p>當尋找添加一個額外的安全層去保護你的機器時，使用OpenDNS的安全DNS框架可能會有幫助。因特網有許多部分組成，盡力對其每一部分都進行相應保護是保證安全的最好方法。</p><p>首先，你要在你的電腦上安裝反病毒和反間諜軟件。由於瀏覽因特網時允許你的電腦查詢遠程DNS服務器，因此使用受保護的安全的DNS服務器將是保護你電腦安全的好方法。（譯註：我們認為，其實在Ubuntu上使用反病毒和反間諜軟件並不太必要，但是使用OpenDNS來攔截對惡意網址的訪問是有必要的。另外，使用國外的DNS可能會比較慢，也許過一段時間，國內也會出現類似的服務。）</p><p>這是一個簡明手冊，告訴你如何在Ubuntu上配置OpenDNS框架以便保護你的電腦。</p><pre><code>sudo gedit /etc/dhcp/dhclient.conf
</code></pre><p>最後，在打開的文件中添加下面一行，然後保存。</p><pre><code>supersede domain-name-servers 208.67.222.222,208.67.220.220;
</code></pre><p>重啓你的電腦，祝你玩的開心！</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/opendns-ubuntu.png" alt=""></p><p>好好享受吧！</p><hr>`,15)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsprotect-your-computers-using-opendns-secure-dns-infrastructure/"},{default:p(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsprotect-your-computers-using-opendns-secure-dns-infrastructure/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：",-1)),u(n,{href:"https://github.com/Linux-pdz"},{default:p(()=>[...t[2]||(t[2]=[e("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),u(n,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const U=s(l,[["render",D]]);export{C as __pageData,U as default};
